"""Max-size structural stress: 32 fields, K=8, 20 heavy quantified atoms,
100 train / 14 probe / 14 query traces, near-max contexts."""
import json, random, sys, subprocess, time
from collections import Counter

def build(seed=0):
    rnd = random.Random(seed)
    schema = []
    for i in range(32):
        t = ['TIME', 'SIZE', 'COUNT', 'ID', 'FLAG'][i % 5]
        name = 'f%02d' % i
        if t == 'ID':
            schema.append({'name': name, 'type': 'ID',
                           'values': ['v%d' % j for j in range(6)]})
        elif t == 'FLAG':
            schema.append({'name': name, 'type': 'FLAG'})
        else:
            schema.append({'name': name, 'type': t, 'min': -20, 'max': 20})
    numeric = [f for f in schema if f['type'] in ('TIME', 'SIZE', 'COUNT')]
    K = 8

    def heavy_atom(idx):
        # quantifier over the whole window, predicate with ~28 term nodes
        fi = idx % len(numeric)
        fname = numeric[fi]['name']
        ftype = numeric[fi]['type']
        # left: add(scale(field $), add(field 0, aggregate over 3 rows))
        left = {'add': [
            {'scale': (idx % 7) + 1, 'term': {'field': fname, 'at': '$'}},
            {'add': [
                {'field': numeric[(idx + 1) % len(numeric)]['name'], 'at': idx % K},
                {'aggregate': 'sum', 'field': numeric[(idx + 2) % len(numeric)]['name'],
                 'from': 0, 'to': 2}]}]}
        right = {'add': [
            {'scale': -((idx % 5) + 1), 'term': {'field': fname, 'at': '$'}},
            {'const': (idx % 17) - 8, 'type': ftype}]}
        return {'quantifier': 'all', 'from': 0, 'to': K - 1,
                'predicate': {'cmp': 'ge', 'left': left, 'right': right}}

    atoms = [heavy_atom(i) for i in range(20)]

    def rand_row():
        vals = []
        for f in schema:
            if f['type'] == 'ID':
                vals.append(rnd.choice(f['values']))
            elif f['type'] == 'FLAG':
                vals.append(rnd.random() < 0.5)
            else:
                vals.append(rnd.randint(-20, 20))
        return vals

    def trace(tid, src, n):
        return {'id': tid, 'source': src,
                'rows': [{'t': i, 'values': rand_row()} for i in range(n)]}

    train = [trace('T%02d' % i, 's%d' % (i % 16), 48) for i in range(100)]
    probes = [trace('P%02d' % i, 's0', 16) for i in range(14)]
    queries = [trace('Q%02d' % i, 's0', 80) for i in range(14)]
    return {'version': 1, 'schema': schema, 'window': K, 'atoms': atoms,
            'policy': {'max_width': 4, 'min_support': 1, 'min_witness': 1},
            'train': train, 'probes': probes, 'queries': queries}

if __name__ == '__main__':
    req = build()
    data = json.dumps(req).encode()
    print('input bytes', len(data), file=sys.stderr)
    t0 = time.time()
    p = subprocess.run([sys.executable, '/app/submission/main.py'], input=data,
                       capture_output=True)
    el = time.time() - t0
    print('rc=%d wall=%.2fs %s' % (p.returncode, el, p.stderr.decode()[-500:]))
    r = json.loads(p.stdout.decode())
    if 'error' in r:
        print('ERROR', r)
    else:
        print('classes=%d members=%d queries=%d' % (
            len(r['classes']), sum(c['members'] for c in r['classes']), len(r['queries'])))
        print('statuses', Counter(q['status'] for q in r['queries']))
